/**
 * Sender-side validation utilities.
 *
 * This module provides validation functions that should be called during sender
 * initialization to detect invalid configuration states before any work begins.
 *
 * Reference: docs/notes/bf-4pc5-sender-compression-resume-detection.md
 */

/**
 * Error thrown when compression and resume are both enabled.
 *
 * This is an architecturally invalid state because:
 * - CompressionStream offers no determinism guarantee across browser restarts
 * - Re-compression after staging reaping (E11) may produce different bytes
 * - Different bytes → different block boundaries → different hashes
 * - Receiver's persisted bitmap would become silently invalid
 *
 * Solution: Disable resume when compression is enabled (set ResumeDisabled flag)
 */
export class CompressionResumeConflictError extends Error {
  constructor() {
    super(
      'Compression and resume cannot both be enabled. ' +
      'When compression is enabled, resume is NOT supported because ' +
      'CompressionStream offers no determinism guarantee across browser restarts. ' +
      'This would silently corrupt the receiver\'s persisted state.'
    );
    this.name = 'CompressionResumeConflictError';
  }
}

/**
 * Validate sender configuration before starting a session.
 *
 * This function implements fail-fast detection of invalid states that would
 * corrupt receiver state or produce undefined behavior. Call this during
 * sender initialization, before any staging files are created or read.
 *
 * **Critical checks:**
 * - Compression and resume are mutually exclusive (bf-4pc5)
 *
 * @param config - Sender configuration to validate
 * @throws {CompressionResumeConflictError} If both compression and resume are enabled
 * @throws {TypeError} If configuration parameters are invalid
 */
export function validateSenderConfig(config: SenderConfig): void {
  // Check 1: Compression and resume are mutually exclusive
  if (config.compressionEnabled && config.resumeEnabled) {
    throw new CompressionResumeConflictError();
  }

  // Future validation checks can be added here
  // Examples:
  // - Validate K doesn't exceed receiver's benchmarked K_max
  // - Validate block size is within acceptable range
  // - Validate file size doesn't exceed storage quota
}

/**
 * Sender configuration interface.
 *
 * This represents the configurable parameters for a sender session.
 * Additional fields can be added as the sender implementation evolves.
 */
export interface SenderConfig {
  /**
   * Whether compression is enabled (D8).
   *
   * When true, the sender compresses the file to a staging file before blocking.
   * This disables resume (resumeEnabled must be false).
   */
  compressionEnabled: boolean;

  /**
   * Whether resume mode is enabled (D22).
   *
   * When true, the sender supports resuming interrupted transfers.
   * This requires compression to be disabled (compressionEnabled must be false).
   */
  resumeEnabled: boolean;

  // Additional configuration fields can be added here as needed:
  // K?: number;           // LT code parameter
  // blockSize?: number;   // Block size in bytes
  // fragmentLen?: number; // Fragment length L
}

/**
 * Check if a sender configuration is valid without throwing.
 *
 * This is a non-throwing version of validateSenderConfig() for use cases
 * where you need to check validity without exception handling overhead.
 *
 * @param config - Sender configuration to validate
 * @returns true if configuration is valid, false otherwise
 */
export function isValidSenderConfig(config: SenderConfig): boolean {
  try {
    validateSenderConfig(config);
    return true;
  } catch {
    return false;
  }
}

/**
 * Get an error message for invalid configuration.
 *
 * Returns a user-friendly error message explaining why the configuration
 * is invalid. Returns null if the configuration is valid.
 *
 * @param config - Sender configuration to check
 * @returns Error message string, or null if configuration is valid
 */
export function getValidationError(config: SenderConfig): string | null {
  try {
    validateSenderConfig(config);
    return null;
  } catch (e) {
    if (e instanceof Error) {
      return e.message;
    }
    return 'Unknown validation error';
  }
}

/**
 * Sender validation tests (bf-4pc5).
 *
 * Tests the sender-side detection for compression+resume conflict.
 *
 * These tests ensure that:
 * 1. Compression and resume cannot both be enabled
 * 2. The validation function throws appropriately
 * 3. Non-throwing variants work correctly
 *
 * See: docs/notes/bf-4pc5-sender-compression-resume-detection.md
 */

import {describe, it, expect} from 'vitest';
import {
  validateSenderConfig,
  isValidSenderConfig,
  getValidationError,
  CompressionResumeConflictError,
  type SenderConfig,
} from '../src/core/sender-validation.js';

describe('Sender validation (bf-4pc5)', () => {
  describe('validateSenderConfig()', () => {
    it('should accept compression enabled without resume', () => {
      const config: SenderConfig = {
        compressionEnabled: true,
        resumeEnabled: false,
      };
      expect(() => validateSenderConfig(config)).not.toThrow();
    });

    it('should accept resume enabled without compression', () => {
      const config: SenderConfig = {
        compressionEnabled: false,
        resumeEnabled: true,
      };
      expect(() => validateSenderConfig(config)).not.toThrow();
    });

    it('should accept both compression and resume disabled', () => {
      const config: SenderConfig = {
        compressionEnabled: false,
        resumeEnabled: false,
      };
      expect(() => validateSenderConfig(config)).not.toThrow();
    });

    it('should throw when both compression and resume are enabled', () => {
      const config: SenderConfig = {
        compressionEnabled: true,
        resumeEnabled: true,
      };
      expect(() => validateSenderConfig(config)).toThrow(CompressionResumeConflictError);
    });

    it('should throw with correct error type', () => {
      const config: SenderConfig = {
        compressionEnabled: true,
        resumeEnabled: true,
      };
      expect(() => validateSenderConfig(config)).toThrow(CompressionResumeConflictError);
      expect(() => validateSenderConfig(config)).toThrow('Compression and resume cannot both be enabled');
    });

    it('should provide detailed error message', () => {
      const config: SenderConfig = {
        compressionEnabled: true,
        resumeEnabled: true,
      };
      try {
        validateSenderConfig(config);
        expect.fail('Should have thrown');
      } catch (e) {
        expect(e).toBeInstanceOf(CompressionResumeConflictError);
        const error = e as CompressionResumeConflictError;
        expect(error.message).toContain('Compression and resume cannot both be enabled');
        expect(error.message).toContain('CompressionStream');
        expect(error.message).toContain('determinism');
      }
    });
  });

  describe('isValidSenderConfig()', () => {
    it('should return true for valid config with compression', () => {
      const config: SenderConfig = {
        compressionEnabled: true,
        resumeEnabled: false,
      };
      expect(isValidSenderConfig(config)).toBe(true);
    });

    it('should return true for valid config with resume', () => {
      const config: SenderConfig = {
        compressionEnabled: false,
        resumeEnabled: true,
      };
      expect(isValidSenderConfig(config)).toBe(true);
    });

    it('should return true for both disabled', () => {
      const config: SenderConfig = {
        compressionEnabled: false,
        resumeEnabled: false,
      };
      expect(isValidSenderConfig(config)).toBe(true);
    });

    it('should return false when both are enabled', () => {
      const config: SenderConfig = {
        compressionEnabled: true,
        resumeEnabled: true,
      };
      expect(isValidSenderConfig(config)).toBe(false);
    });
  });

  describe('getValidationError()', () => {
    it('should return null for valid config with compression', () => {
      const config: SenderConfig = {
        compressionEnabled: true,
        resumeEnabled: false,
      };
      expect(getValidationError(config)).toBeNull();
    });

    it('should return null for valid config with resume', () => {
      const config: SenderConfig = {
        compressionEnabled: false,
        resumeEnabled: true,
      };
      expect(getValidationError(config)).toBeNull();
    });

    it('should return null for both disabled', () => {
      const config: SenderConfig = {
        compressionEnabled: false,
        resumeEnabled: false,
      };
      expect(getValidationError(config)).toBeNull();
    });

    it('should return error message when both are enabled', () => {
      const config: SenderConfig = {
        compressionEnabled: true,
        resumeEnabled: true,
      };
      const error = getValidationError(config);
      expect(error).not.toBeNull();
      expect(error).toContain('Compression and resume cannot both be enabled');
    });

    it('should return specific error message mentioning CompressionStream', () => {
      const config: SenderConfig = {
        compressionEnabled: true,
        resumeEnabled: true,
      };
      const error = getValidationError(config);
      expect(error).not.toBeNull();
      expect(error).toContain('CompressionStream');
      expect(error).toContain('determinism');
    });
  });

  describe('CompressionResumeConflictError', () => {
    it('should be an Error instance', () => {
      const error = new CompressionResumeConflictError();
      expect(error).toBeInstanceOf(Error);
    });

    it('should have correct name', () => {
      const error = new CompressionResumeConflictError();
      expect(error.name).toBe('CompressionResumeConflictError');
    });

    it('should have descriptive message', () => {
      const error = new CompressionResumeConflictError();
      expect(error.message).toContain('Compression and resume cannot both be enabled');
      expect(error.message).toContain('CompressionStream');
      expect(error.message).toContain('determinism');
    });
  });

  describe('Integration scenarios', () => {
    it('should catch configuration error before sender starts', () => {
      // Scenario: Sender initialization checks configuration before any work begins
      const config: SenderConfig = {
        compressionEnabled: true,
        resumeEnabled: true,  // Invalid!
      };

      // Before creating staging files or starting transmission
      expect(() => validateSenderConfig(config)).toThrow();

      // This prevents:
      // 1. Creating staging files that would be corrupted on resume
      // 2. Emitting beacons with invalid flag combinations
      // 3. Silently corrupting receiver state
    });

    it('should allow sender to proceed with compression-only', () => {
      // Scenario: User wants fast transfer, accepts no resume
      const config: SenderConfig = {
        compressionEnabled: true,
        resumeEnabled: false,
      };

      expect(() => validateSenderConfig(config)).not.toThrow();
      // Sender can proceed to:
      // 1. Create compressed staging file
      // 2. Set BeaconFlags.Compressed | BeaconFlags.ResumeDisabled
      // 3. Start transmission
    });

    it('should allow sender to proceed with resume-only', () => {
      // Scenario: User wants robust multi-hour transfer
      const config: SenderConfig = {
        compressionEnabled: false,
        resumeEnabled: true,
      };

      expect(() => validateSenderConfig(config)).not.toThrow();
      // Sender can proceed to:
      // 1. Read file directly (no compression)
      // 2. Set BeaconFlags.None (resume enabled)
      // 3. Start transmission with resume support
    });

    it('should allow sender to proceed with neither', () => {
      // Scenario: User doesn't need compression or resume
      const config: SenderConfig = {
        compressionEnabled: false,
        resumeEnabled: false,
      };

      expect(() => validateSenderConfig(config)).not.toThrow();
      // Sender can proceed to:
      // 1. Read file directly
      // 2. Set BeaconFlags.None
      // 3. Start transmission
    });
  });
});
